import { compactAuditResult, compactVerifyReport, errorResponse, text, } from "../types.js";
// ---- inspection (W2): evidence-only runtime + a11y + local aggregates ----
export async function audit_url(ctx, args) {
    try {
        const audit = ctx.deps.auditUrlFn ??
            ((a) => import("../../audit-url.js").then((m) => m.auditUrl(a.url, { viewport: a.viewport, timeoutMs: a.timeoutMs })));
        const result = await audit({
            url: args.url,
            viewport: args.viewport,
            timeoutMs: args.timeoutMs,
        });
        if ("error" in result)
            return { content: [text(result.error)], isError: true };
        // compact=true: severity counts + ranked actions instead of every finding.
        const payload = args.compact ? compactAuditResult(result) : result;
        return { content: [text(JSON.stringify(payload, null, 1))] };
    }
    catch (err) {
        return errorResponse(err);
    }
}
